problem:
Problem description
- There is a single planning horizon $$\mathcal{H}$$ with a set of main products indexed by $$p \in \mathcal{P}$$, a set of reaction stages indexed by $$r \in \mathcal{R}$$, and a set of byproducts indexed by $$k \in \mathcal{K}$$.
- Each unit of main product $$p$$ requires a fixed amount of processing time $$t_{rp}$$ at each reaction stage $$r$$.
- Each reaction stage $$r$$ has an available time capacity $$T_r$$ within $$\mathcal{H}$$.
- Producing main product $$p$$ may generate byproduct $$k$$ according to a fixed yield coefficient $$a_{kp}$$, and byproduct generation does not add any extra production cost.
- Each main product $$p$$ yields a unit profit $$\pi_p$$ when sold.
- Each byproduct $$k$$ yields a unit profit $$\rho_k$$ when sold, may be sold only up to a limited amount $$L_k$$, and any remaining byproduct must be disposed of at unit cost $$c_k$$.
- The planning goal is to choose production and byproduct disposition quantities so that total profit over $$\mathcal{H}$$ is maximized.
- Required business constraints:
  - Every produced unit must respect the available time capacity of each reaction stage.
  - Byproduct generation must be consistent with the chosen production quantities of the main products.
  - Byproduct sales must not exceed the sale limit for each byproduct.
  - Any byproduct that is not sold must be disposed of and incur disposal cost.
  - All decision variables must be nonnegative.
- A solution is represented by:
  - $$x_p$$: quantity of main product $$p$$ produced and sold during $$\mathcal{H}$$.
  - $$y_k$$: quantity of byproduct $$k$$ sold during $$\mathcal{H}$$.
  - $$z_k$$: quantity of byproduct $$k$$ disposed of during $$\mathcal{H}$$.
  - $$Z$$: total profit achieved over $$\mathcal{H}$$.

Input Format
{
  "planning_horizon": {
    "symbol": "$$\\mathcal{H}$$",
    "meaning": "single aggregate planning horizon"
  },
  "products": {
    "symbol": "$$\\mathcal{P}$$",
    "type": "array of strings",
    "shape": "$$|\\mathcal{P}|$$",
    "meaning": "list of main products"
  },
  "byproducts": {
    "symbol": "$$\\mathcal{K}$$",
    "type": "array of strings",
    "shape": "$$|\\mathcal{K}|$$",
    "meaning": "list of byproducts"
  },
  "processes": {
    "symbol": "$$\\mathcal{R}$$",
    "type": "array of strings",
    "shape": "$$|\\mathcal{R}|$$",
    "meaning": "list of reaction stages"
  },
  "processing_time": {
    "symbol": "$$t_{rp}$$",
    "type": "matrix",
    "shape": "$$|\\mathcal{R}| \\times |\\mathcal{P}|$$",
    "meaning": "hours required at reaction stage $$r$$ for one unit of product $$p$$"
  },
  "process_capacity": {
    "symbol": "$$T_r$$",
    "type": "vector",
    "shape": "$$|\\mathcal{R}|$$",
    "meaning": "available hours for each reaction stage $$r$$"
  },
  "byproduct_yield": {
    "symbol": "$$a_{kp}$$",
    "type": "matrix",
    "shape": "$$|\\mathcal{K}| \\times |\\mathcal{P}|$$",
    "meaning": "units of byproduct $$k$$ generated per unit of product $$p$$"
  },
  "main_product_profit": {
    "symbol": "$$\\pi_p$$",
    "type": "vector",
    "shape": "$$|\\mathcal{P}|$$",
    "meaning": "profit per sold unit of main product $$p$$"
  },
  "byproduct_sale_profit": {
    "symbol": "$$\\rho_k$$",
    "type": "vector",
    "shape": "$$|\\mathcal{K}|$$",
    "meaning": "profit per sold unit of byproduct $$k$$"
  },
  "byproduct_sale_limit": {
    "symbol": "$$L_k$$",
    "type": "vector",
    "shape": "$$|\\mathcal{K}|$$",
    "meaning": "maximum sellable quantity of byproduct $$k$$"
  },
  "byproduct_disposal_cost": {
    "symbol": "$$c_k$$",
    "type": "vector",
    "shape": "$$|\\mathcal{K}|$$",
    "meaning": "disposal cost per unit of byproduct $$k$$"
  }
}

Output Format
{
  "production_plan": {
    "symbol": "$$x_p$$",
    "type": "vector",
    "shape": "$$|\\mathcal{P}|$$",
    "meaning": "produced and sold quantity of each main product $$p$$"
  },
  "byproduct_sales": {
    "symbol": "$$y_k$$",
    "type": "vector",
    "shape": "$$|\\mathcal{K}|$$",
    "meaning": "sold quantity of each byproduct $$k$$"
  },
  "byproduct_disposal": {
    "symbol": "$$z_k$$",
    "type": "vector",
    "shape": "$$|\\mathcal{K}|$$",
    "meaning": "disposed quantity of each byproduct $$k$$"
  },
  "objective_value": {
    "symbol": "$$Z$$",
    "type": "scalar",
    "meaning": "maximum total profit"
  }
}

