    "A": [2, 3],
    "B": [3, 4]
  },
  "process_capacity": {
    "reaction_1": 16,
    "reaction_2": 24
  },
  "byproduct_yield": {
    "C": {
      "A": 0,
      "B": 2
    }
  },
  "main_product_profit": {
    "A": 4,
    "B": 10
  },
  "byproduct_sale_profit": {
    "C": 3
  },
  "byproduct_sale_limit": {
    "C": 5
  },
  "byproduct_disposal_cost": {
    "C": 2
  }
}
